1	// The fleet-baseline DISPATCH — the enforcer's manual lever over the whole fleet:
2	// force every covered member to baseline NOW, instead of waiting for each one's next
3	// anchor. It dispatches each member's OWN scheduler with `wake: update` —
4	// the same button the owner would press in that repo's Actions tab, pressed across
5	// the fleet in one run. Nothing is baselined here: each member converges its own
6	// mount, with its own token, under its own scheduler and its own delivery policy.
7	// This is a dispatcher, not a maintainer — the fan-out model this pack runs both its
8	// write-shaped operations on (#749).
9	//
10	// IT FOLLOWS EACH MEMBER TO CURRENT (owner decision, #1293). A dispatch queues a run;
11	// reporting those queued runs reports this sweep's own outgoing calls rather than the
12	// fleet, and reads as delivery when it was not — #1292 recorded `13 fired, 0 failed`
13	// where 9 of the 13 took nothing. So the run's deliverable is the OUTCOME table: which
14	// members stamp canon's published engine and pack versions, which were already there,
15	// and which did not get there.
16	//
17	// This is not #649's 45-minute sleep returning. That was a blind fixed wait every run
18	// paid whatever the fleet was doing, and it forced the lever to be a standalone
19	// workflow. follow-to-current.mjs polls a real terminal condition instead, and each
20	// member leaves the loop the moment it reads current — an already-current fleet
21	// finishes on the first pass, in seconds, and the lever stays an ordinary manual task.
22	//
23	// WHY IT EXISTS. Under per-project scheduling every member baselines itself hourly,
24	// so the fleet needs no push in the ordinary case. The cases it is FOR are the
25	// un-ordinary ones: a canon change the fleet should pick up now rather than over the
26	// next day, and the tail of members whose next anchor is hours away. A wake clears
27	// the item's wait and re-readies it; the executor still evaluates the task's own
28	// precondition at pick, so a member with nothing to do converges to a cheap no-op —
29	// safe to over-use, only wasteful.
30	//
31	// THE TOKEN. FLEET_GITHUB_TOKEN, the same account-spanning PAT the sweeps use, plus
32	// ONE scope the read-only ones do not need: **Actions: read and write** on the
33	// owner's repositories. Dispatching another repo's workflow is a write to that
34	// repo's Actions, and a PAT scoped only for the sweeps gets a 403 here — reported
35	// per repo and failing the run, because it is a grant to fix once, not a transient.
36	//
37	// Dependency-free (global fetch, Node 20+). It writes NOTHING to any member — no
38	// commit, no issue, no comment; the single side effect per member is one queued
39	// Actions run.
40	
41	import { appendFileSync } from 'node:fs';
42	import { pathToFileURL } from 'node:url';
43	import {
44	  makeGh, paged, readDeclaration, isDormant, DECLARATION, SCHEDULER, fireScheduler,
45	} from '../../fleet-api.mjs';
46	import { parseSheepdogConfig } from '../../fleet-config.mjs';
47	import { missingFleetTokenError } from '../../fleet-token.mjs';
48	import { classifyFreshness, probeMount, FRESH } from '../fleet-roster/drift-issues.mjs';
49	import {
50	  canonVersions, followToCurrent, isSuccess,
51	  ALREADY_CURRENT, CONVERGED, NEVER_STARTED, DID_NOT_CONVERGE, UNKNOWN,
52	} from './follow-to-current.mjs';
53	
54	// The exact member-side task this lever forces — the id the member's scheduler run resolves
55	// against its own declared packs (`planWake` in packs/claudinite-tasks/queue/scheduler-run.mjs);
56	// named as a constant so the coupling is one line to find, not a string buried in a
57	// request body.
58	//
59	// `update` since Phase 5 (#768): the task this lever used to force no longer exists,
60	// and a lever that dispatches a task nothing will run reports a successful dispatch
61	// for a member that then does nothing — the exact "counts dispatches, not outcomes"
62	// blindness this sweep already has (Sheepdog#172). The task's own NAME is still the
63	// old vocabulary; renaming it is the fleet-wide update lever's work, not this line's.
64	export const FORCED_TASK = 'update';
65	
66	// How long the follow will wait for the whole fleet to read current before giving up
67	// on whatever is left. Sized from what a member's update actually takes end to end —
68	// vendor, migrate, open the maintenance PR, auto-merge it, and on some members an
69	// agent apply stage after that — which was measured at 5–10 minutes, so the default
70	// leaves room for the slow tail without being a fixed wait anybody pays: every member
71	// leaves the loop the moment it reads current.
72	export const DEFAULT_FOLLOW_MINUTES = 20;
73	
74	// The `REPOS` parameter, resolved against the owner: a space/whitespace-separated list
75	// of bare names or full `owner/name`, lowercased, or null for "every member". A bare
76	// name is qualified with the configured owner, because that is the only owner this
77	// sweep can reach and typing it twenty times is friction with no upside.
78	// Space-separated, never comma-separated — the parameter bag splits keys on commas.
79	export function parseRepoFilter(raw, owner) {
80	  const names = String(raw ?? '').split(/\s+/).map((s) => s.trim()).filter(Boolean);
81	  if (!names.length) return null;
82	  return new Set(names.map((n) => (n.includes('/') ? n : `${owner}/${n}`).toLowerCase()));
83	}
84	
85	// Why a repo is out of this dispatch's scope BEFORE its declaration is even read —
86	// or null when it is in scope. Every branch lands in the report's skipped list,
87	// never a silent `continue`: the report enumerates the full fleet, and a fleet-wide
88	// force whose report names only the dispatched members reads as fleet-wide coverage
89	// when it was not. (Canon is skipped because its baselining self-skips — but the
90	// enforcer repo is NOT exempt: it is an ordinary member with a mount to converge,
91	// and leaving it out would make the one repo the owner is looking at the one repo
92	// that did not move.) Kept free of I/O so every branch is testable directly.
93	export function classifyScope(r, { canonRepo, exclude, filter }) {
94	  const fullName = r.full_name.toLowerCase();
95	  if (fullName === canonRepo.toLowerCase()) {
96	    return { state: 'canon', detail: 'canon has no vendored mount — forcing it would queue a run whose only outcome is its own self-skip' };
97	  }
98	  if (r.archived || r.fork) return { state: 'out-of-scope', detail: r.archived ? 'archived' : 'a fork' };
99	  if (exclude.has(fullName)) return { state: 'excluded', detail: "on the claudinite-fleet-sheepdog config's exclude list" };
100	  if (filter && !filter.has(fullName)) return { state: 'filtered-out', detail: "not in this run's REPOS filter" };
101	  return null;
102	}
103	
104	// --- main ---------------------------------------------------------------------
105	
106	export async function main() {
107	  const token = process.env.FLEET_GITHUB_TOKEN;
108	  const home = process.env.GITHUB_REPOSITORY;
109	  if (!token) {
110	    throw missingFleetTokenError('fleet-baseline',
111	      'The default GITHUB_TOKEN sees only this repo and cannot dispatch another repo\'s workflow.');
112	  }
113	  if (!home || !home.includes('/')) throw new Error('GITHUB_REPOSITORY is not set (owner/repo)');
114	  const gh = makeGh(token);
115	
116	  const dryRun = String(process.env.FLEET_BASELINE_DRY_RUN ?? '').toLowerCase() === 'true';
117	  const includeDormant = String(process.env.FLEET_BASELINE_INCLUDE_DORMANT ?? '').toLowerCase() === 'true';
118	
119	  const cfgRes = await gh(`/repos/${home}/contents/${DECLARATION}`);
120	  if (cfgRes.status !== 200 || !cfgRes.json?.content) {
121	    throw new Error(`the claudinite-fleet-sheepdog repo ${home} has no readable ${DECLARATION} (status ${cfgRes.status})`);
122	  }
123	  let cfg;
124	  try { cfg = JSON.parse(Buffer.from(cfgRes.json.content, 'base64').toString('utf8')); } catch (e) {
125	    throw new Error(`unparsable ${DECLARATION} on ${home}: ${e.message}`);
126	  }
127	  const { owner, exclude, canonRepo } = parseSheepdogConfig(cfg, home);
128	  const filter = parseRepoFilter(process.env.FLEET_BASELINE_REPOS, owner);
129	  // One reader for the whole sweep: it memoizes canon's engine version and each
130	  // pack's, so canon is read once per distinct pack rather than once per member.
131	  const canon = canonVersions(gh, canonRepo);
132	  const followMinutes = Number(process.env.FLEET_BASELINE_FOLLOW_MINUTES) || DEFAULT_FOLLOW_MINUTES;
133	
134	  const mine = (await paged(gh, '/user/repos?affiliation=owner'))
135	    .filter((r) => r.owner.login.toLowerCase() === owner);
136	  if (mine.length === 0) {
137	    throw new Error(`enumeration returned no repos owned by ${owner} — wrong token user or scope`);
138	  }
139	
140	  const fired = []; const skipped = []; const failed = [];
141	  for (const r of mine.sort((a, b) => a.name.localeCompare(b.name))) {
142	    const fullName = r.full_name.toLowerCase();
143	    // Out of scope before the declaration is read — canon, archived, a fork, excluded,
144	    // or filtered out. classifyScope says why, and each lands in the skipped list: no
145	    // repo leaves this report silently, whatever its state.
146	    const scope = classifyScope(r, { canonRepo, exclude, filter });
147	    if (scope) { skipped.push({ fullName, ...scope }); continue; }
148	
149	    let decl;
150	    try {
151	      decl = await readDeclaration(gh, r.full_name);
152	    } catch (e) {
153	      // Unreadable is not uncovered: a repo whose declaration could not be read might be
154	      // a member that needed this run, so it is a FAILURE to escalate, never a silent skip.
155	      failed.push({ fullName, state: 'error', detail: `could not read ${DECLARATION}: ${e.message}` });
156	      continue;
157	    }
158	    if (decl === null) {
159	      skipped.push({ fullName, state: 'uncovered', detail: `no tracked ${DECLARATION} — adoption is the census's business, and there is nothing there to baseline` });
160	      continue;
161	    }
162	    if (isDormant(decl) && !includeDormant) {
163	      // A dormant member stopped its own scheduler; a forced dispatch on it either does
164	      // nothing (the run stops before evaluating anything) or wakes a repo that asked to
165	      // sleep. Reported, not silently dropped, so a fleet-wide force is never mistaken
166	      // for fleet-wide coverage.
167	      skipped.push({ fullName, state: 'dormant', detail: 'self-declared dormant — pass INCLUDE_DORMANT=true to force it anyway' });
168	      continue;
169	    }
170	
171	    if (dryRun) {
172	      fired.push({ fullName, state: 'would-fire', detail: `would dispatch ${SCHEDULER}@${r.default_branch} to wake ${FORCED_TASK}` });
173	      continue;
174	    }
175	    // BEFORE firing, not after: a member already at canon's versions declines its own
176	    // update and never does any work, and only a reading taken before the dispatch can
177	    // tell that success apart from a member that converged because of it. The
178	    // declaration is already in hand, so this costs the mount probe alone.
179	    let wasFresh = false;
180	    try {
181	      wasFresh = classifyFreshness(await probeMount(gh, r.full_name, decl, { canon })).state === FRESH;
182	    } catch {
183	      // Unreadable here is not a failure to dispatch. It only means this member's
184	      // success will be reported as `converged` rather than `already-current`, which
185	      // is the conservative way round: it claims no more than was observed.
186	      wasFresh = false;
187	    }
188	    const firedAt = new Date().toISOString();
189	    const verdict = await fireScheduler(gh, r.full_name, r.default_branch, FORCED_TASK);
190	    if (verdict.state !== 'fired') { failed.push({ fullName, ...verdict }); continue; }
191	    fired.push({ fullName, ...verdict, firedAt, wasFresh });
192	  }
193	
194	  // THE FOLLOW. Everything above queued runs; this is what turns that into an answer
195	  // about the FLEET. Skipped for a dry run, which dispatched nothing and therefore has
196	  // no outcome to wait for.
197	  const followed = dryRun || fired.length === 0 ? [] : await followToCurrent(gh, fired, {
198	    canon,
199	    readDeclaration,
200	    budgetMs: followMinutes * 60_000,
201	    sleep: (ms) => new Promise((resolve) => setTimeout(resolve, ms)),
202	    log: (line) => console.log(line),
203	  });
204	
205	  const summary = renderBaselineReport({ owner, dryRun, filter, fired, followed, skipped, failed });
206	  console.log(summary);
207	  if (process.env.GITHUB_STEP_SUMMARY) appendFileSync(process.env.GITHUB_STEP_SUMMARY, `${summary}\n`);
208	
209	  const problem = runVerdict({ fired, followed, failed });
210	  if (problem) throw new Error(problem);
211	}
212	
213	const runsUrl = (n) => `https://github.com/${n}/actions/workflows/${SCHEDULER}`;
214	
215	// Each outcome gets its own section, because each is a different thing for the reader
216	// to do — and because collapsing `already-current` into the successes without naming
217	// it would hide the single most useful fact a run can report: that a member needed
218	// nothing. Ordered as the reader wants them: what moved, what was fine, then what to
219	// go and fix.
220	export const OUTCOME_SECTIONS = [
221	  [CONVERGED, 'Converged during this run', 'was behind canon and is now at its versions'],
222	  [ALREADY_CURRENT, 'Already current', "was at canon's versions before the dispatch, so its own update correctly declined"],
223	  [DID_NOT_CONVERGE, 'Started but did not reach canon', 'its scheduler ran — go and read it'],
224	  [NEVER_STARTED, 'Never started', 'the dispatch was accepted and no run followed it'],
225	  [UNKNOWN, 'Could not be determined', 'the member could not be read'],
226	];
227	
228	// The whole report, pure over what the sweep observed — so what it CLAIMS is testable
229	// without a fleet. The headline count is `current of dispatched`, never a count of
230	// dispatches: a table whose big number is "13 fired" is the thing #1292 caught.
231	export function renderBaselineReport({ owner, dryRun, filter, fired, followed, skipped, failed }) {
232	  const current = followed.filter((f) => isSuccess(f.outcome));
233	  const notCurrent = followed.filter((f) => !isSuccess(f.outcome));
234	  const section = ([state, heading, gloss]) => {
235	    const rows = followed.filter((f) => f.outcome === state);
236	    return rows.length
237	      ? `**${heading}** — ${gloss}:\n${rows.map((f) => `- [\`${f.fullName}\`](${runsUrl(f.fullName)}) — ${f.detail}`).join('\n')}`
238	      : '';
239	  };
240	
241	  return [
242	    `# Fleet baseline — ${owner}${dryRun ? ' (DRY RUN — nothing was dispatched)' : ''}`,
243	    '',
244	    dryRun
245	      ? `Would ask each covered member's own \`${SCHEDULER}\` to wake its \`${FORCED_TASK}\` item.`
246	      : `Asked each covered member's own \`${SCHEDULER}\` to wake its \`${FORCED_TASK}\` item, then followed each`
247	        + ` one until its own \`${DECLARATION}\` stamped the engine and every declared pack at the versions canon publishes.`,
248	    filter ? `Filtered to: ${[...filter].join(', ')}` : '',
249	    '',
250	    dryRun
251	      ? `| would fire | skipped |\n| --- | --- |\n| ${fired.length} | ${skipped.length} |`
252	      : `| current | not current | not dispatched | skipped |\n| --- | --- | --- | --- |\n`
253	        + `| ${current.length} of ${fired.length} | ${notCurrent.length} | ${failed.length} | ${skipped.length} |`,
254	    '',
255	    dryRun && fired.length
256	      ? `**Would fire:**\n${fired.map((f) => `- [\`${f.fullName}\`](${runsUrl(f.fullName)})`).join('\n')}`
257	      : '',
258	    !dryRun && !fired.length && !failed.length
259	      ? '**No member was dispatched** — check the filter, or whether anything under this owner is covered.'
260	      : '',
261	    ...OUTCOME_SECTIONS.map(section),
262	    skipped.length ? `**Skipped:**\n${skipped.map((s) => `- \`${s.fullName}\` — **${s.state}**: ${s.detail}`).join('\n')}` : '',
263	    failed.length ? `**Could not be dispatched:**\n${failed.map((f) => `- \`${f.fullName}\` — **${f.state}**: ${f.detail}`).join('\n')}` : '',
264	    '',
265	    // Said plainly rather than left to inference: "current" is a statement about
266	    // PUBLISHED VERSION NUMBERS. Canon content that shipped without a version bump
267	    // moves no number, so a member can read current and still lack it (#1292).
268	    "_Current means the member stamps canon's published engine and pack versions. Canon content_",
269	    '_that shipped without a version bump moves no number, so it is invisible here._',
270	  ].filter(Boolean).join('\n');
271	}
272	
273	// What fails the run, in the order a reader should act on it — or null when the fleet
274	// is current. A dispatch that never landed is a grant or an adoption to fix. A member
275	// that WAS dispatched and is still not current is the failure this whole follow exists
276	// to surface: the one the old report counted as a success. Everything observed is
277	// printed before this is consulted, so a throw ends the run without withdrawing the
278	// report. Pure, so the escalation policy is testable without a fleet.
279	export function runVerdict({ fired, followed, failed }) {
280	  if (failed.length) {
281	    return `${failed.length} member(s) could not be dispatched (${failed.map((f) => `${f.fullName}: ${f.state}`).join('; ')}) — `
282	      + 'the rest are reported above, and this run fails so the cause is escalated';
283	  }
284	  const notCurrent = followed.filter((f) => !isSuccess(f.outcome));
285	  if (notCurrent.length) {
286	    return `${notCurrent.length} of ${fired.length} dispatched member(s) did not reach canon's versions `
287	      + `(${notCurrent.map((f) => `${f.fullName}: ${f.outcome}`).join('; ')}) — `
288	      + 'reported above, and this run fails rather than counting the dispatch as the outcome';
289	  }
290	  return null;
291	}
292	
293	const isMain = process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href;
294	if (isMain) {
295	  main().catch((e) => { console.error(`fleet-baseline failed: ${e.message}`); process.exit(1); });
296	}
